using System;using System.IO;using System.Text;using System.Net;using System.Net.Sockets;using System.Threading.Tasks;using System.IO.Compression;using Lumina;
class WeatherTransportTests {
    static int checks;static void Check(bool value,string message){checks++;if(!value)throw new Exception(message);}
    static int Main(){
        string json="{\"current_units\":{\"temperature_2m\":\"°C\"},\"current\":{\"temperature_2m\":18.5,\"weather_code\":3,\"wind_speed_10m\":7.2,\"time\":\"2026-10-26T12:00\"}}";
        using(var stream=new MemoryStream(new UTF8Encoding(true).GetPreamble().Concat(Encoding.UTF8.GetBytes(json)))){var reply=WeatherTransport.Read<WeatherReply>(stream);Check(reply.Current.Temperature==18.5&&reply.Current.Wind==7.2&&reply.Current.Code==3,"BOM, current fields, units and extra JSON fields");}
        foreach(string invalid in new[]{"","<html>blocked</html>","{broken"}){bool rejected=false;try{using(var stream=new MemoryStream(Encoding.UTF8.GetBytes(invalid)))WeatherTransport.Read<WeatherReply>(stream);}catch(InvalidDataException){rejected=true;}Check(rejected,"invalid response diagnosis");}
        bool oversized=false;try{using(var stream=new MemoryStream(new byte[2*1024*1024+1]))WeatherTransport.Read<WeatherReply>(stream);}catch(InvalidDataException){oversized=true;}Check(oversized,"oversized response bounded");
        var request=WeatherTransport.Request("https://api.open-meteo.com/v1/forecast?latitude=30&longitude=120",false);Check(!request.KeepAlive&&request.ProtocolVersion==HttpVersion.Version11&&request.Accept=="application/json","non-pooled valid GET request");Check(request.Timeout==8000&&request.ReadWriteTimeout==8000,"request and body timeouts bounded");
        var direct=WeatherTransport.Request("https://api.open-meteo.com/",true);Check(direct.Proxy==null,"direct route explicitly selected");bool insecure=false;try{WeatherTransport.Request("http://example.com/",false);}catch(ArgumentException){insecure=true;}Check(insecure,"remote insecure transport rejected");
        var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();int port=((IPEndPoint)listener.LocalEndpoint).Port;string headers=null;
        var server=Task.Run(()=>{using(var client=listener.AcceptTcpClient()){client.ReceiveTimeout=5000;using(var stream=client.GetStream()){var reader=new StreamReader(stream,Encoding.ASCII,false,1024,true);var lines=new System.Collections.Generic.List<string>();string line;while(!string.IsNullOrEmpty(line=reader.ReadLine()))lines.Add(line);headers=string.Join("\n",lines);byte[] gzip;using(var data=new MemoryStream()){using(var zipped=new GZipStream(data,CompressionMode.Compress,true)){byte[] bytes=Encoding.UTF8.GetBytes(json);zipped.Write(bytes,0,bytes.Length);}gzip=data.ToArray();}var head=Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Type: application/json; charset=utf-8\r\nContent-Encoding: gzip\r\nConnection: close\r\nContent-Length: "+gzip.Length+"\r\n\r\n");stream.Write(head,0,head.Length);stream.Write(gzip,0,gzip.Length);}}});
        try{var reply=WeatherTransport.Get<WeatherReply>("http://127.0.0.1:"+port+"/weather",true);Check(reply.Current.Temperature==18.5,"actual HTTP compressed body decoded and deserialized");Check(server.Wait(6000),"server completed");Check(headers.Contains("GET /weather HTTP/1.1")&&headers.ToLowerInvariant().Contains("connection: close"),"wire request has GET and connection-close policy");}finally{listener.Stop();}
        Console.WriteLine(checks+" weather HTTP/gzip/BOM/JSON/timeout/proxy/bounds checks PASS; Windows TLS and user network remain untested");return 0;
    }
}
static class BytesForWeather {public static byte[] Concat(this byte[] first,byte[] second){var result=new byte[first.Length+second.Length];Buffer.BlockCopy(first,0,result,0,first.Length);Buffer.BlockCopy(second,0,result,first.Length,second.Length);return result;}}
